// /instant/:runId over the four schema-1.1 fixtures (tests/fixtures/instant/,
// generated by the recipes over synthetic data), against a mocked fetch for
// the run and its export. The Evidence panel is held digit-free: every number
// the user sees lives inside the frame, where the backend verified it.
import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/integrations/supabase/external-client", () => ({
  supabase: {
    auth: { getSession: vi.fn(async () => ({ data: { session: { access_token: "tok-ui" } } })) },
  },
}));

import { DEV_TOKEN_KEY } from "@/lib/api/backendApi";
import {
  instantApi,
  type InstantApi,
  type InstantRun,
  type OutcomeReport11,
} from "@/lib/api/instant";
import { GATE_LABELS, RECIPE_TITLES, STATUS_WORDS, VERDICT_LABELS } from "@/lib/instant-labels";
import { PAYWALL_COPY } from "@/lib/instant-paywall";
import { ReportPage } from "@/components/instant/ReportPage";
import { REPORT_FRAME_MIN_HEIGHT, REPORT_HEIGHT_MESSAGE } from "@/components/instant/ReportFrame";
import { SHARE_PENDING_TITLE } from "@/components/instant/DownloadRow";
import describeFx from "../fixtures/instant/describe_clean_by_dimension.report.json";
import trendFx from "../fixtures/instant/trend_gaps.report.json";
import correlateFx from "../fixtures/instant/correlate_simpsons_paradox.report.json";
import abTestFx from "../fixtures/instant/ab_test_underpowered.report.json";

/** A stand-in for the 1 MB export: same skeleton, same height message, no ECharts. */
const STUB_HTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'sha256-stub'; style-src 'unsafe-inline'; connect-src 'none'">
<meta name="referrer" content="no-referrer">
<title>Avaloka analysis</title>
<style>body{margin:0;font:15px/1.5 sans-serif}.wrap{max-width:980px;margin:0 auto;padding:24px 16px}</style>
</head>
<body>
<div class="wrap">
<header><div class="brand">Avaloka</div><h1>Stub report</h1></header>
<section class="card"><p>Across <span data-fig="f1">600</span> rows the median is <span data-fig="f2">149.17</span>.</p></section>
<section class="card"><div data-chart="distribution" style="height:320px"></div></section>
<footer><small>generator avaloka 2.0.0</small></footer>
</div>
<script type="application/json" id="avaloka-report">{"schema_version":"1.1"}</script>
<script>
(function () {
  "use strict";
  if (window.parent && window.parent !== window) {
    var send = function () {
      window.parent.postMessage({ type: "avaloka-report-height", h: document.documentElement.scrollHeight }, "*");
    };
    window.addEventListener("load", send);
    window.addEventListener("resize", send);
  }
})();
</script>
</body>
</html>
`;

type Fixture = { name: string; report: OutcomeReport11 };
const FIXTURES: Fixture[] = [
  { name: "describe_clean_by_dimension", report: describeFx as unknown as OutcomeReport11 },
  { name: "trend_gaps", report: trendFx as unknown as OutcomeReport11 },
  { name: "correlate_simpsons_paradox", report: correlateFx as unknown as OutcomeReport11 },
  { name: "ab_test_underpowered", report: abTestFx as unknown as OutcomeReport11 },
];

/** A run row as PR-6 stores it, over a fixture report. */
function runOf(fx: Fixture, overrides: Partial<InstantRun> = {}): InstantRun {
  const id = `run-${fx.name}`;
  return {
    run_id: id,
    dataset_id: "ds-fixture",
    recipe: fx.report.provenance!.recipe!,
    verdict: fx.report.completion!.state === "answered" ? "pass" : "qualified",
    question: `A question about ${fx.name}`,
    report: fx.report,
    export_url: `/api/instant/${id}/export.html`,
    notebook_url: `/api/instant/${id}/notebook.ipynb`,
    locked: false,
    ...overrides,
  };
}

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

function pathOf(url: unknown, init?: RequestInit): string {
  return new Headers(init?.headers).get("x-backend-path") ?? String(url);
}

describe("/instant/:runId", () => {
  const fetchSpy = vi.fn<typeof fetch>();
  const api: InstantApi = { ...instantApi };

  /** Serve one run and its export; anything else is 404. */
  function serve(run: InstantRun, html = STUB_HTML) {
    fetchSpy.mockImplementation(async (url, init) => {
      const path = pathOf(url, init);
      if (path === `/api/instant/${run.run_id}`) return json(run);
      if (path === run.export_url)
        return new Response(html, { status: 200, headers: { "Content-Type": "text/html" } });
      return new Response("not found", { status: 404 });
    });
  }

  beforeEach(() => {
    fetchSpy.mockReset();
    vi.stubGlobal("fetch", fetchSpy);
    localStorage.removeItem(DEV_TOKEN_KEY);
  });
  afterEach(() => vi.unstubAllGlobals());

  const calledPaths = () => fetchSpy.mock.calls.map(([u, i]) => pathOf(u, i as RequestInit));

  async function renderRun(run: InstantRun, onReady?: (id: string) => void) {
    serve(run);
    render(<ReportPage runId={run.run_id} api={api} onReady={onReady} />);
    await waitFor(() => expect(screen.getByTestId("instant-report-header")).toBeTruthy());
    return run;
  }

  describe.each(FIXTURES)("$name", (fx) => {
    it("names the recipe, the verdict and the question in the header", async () => {
      const run = await renderRun(runOf(fx));
      expect(screen.getByTestId("instant-recipe-title").textContent).toBe(
        RECIPE_TITLES[run.recipe.id as keyof typeof RECIPE_TITLES],
      );
      expect(screen.getByTestId("instant-verdict").textContent).toBe(VERDICT_LABELS[run.verdict]);
      expect(screen.getByTestId("instant-question").textContent).toBe(run.question);
      expect(calledPaths()).toContain(`/api/instant/${run.run_id}`);
    });

    it("Evidence: one row per data_check, the right status word, the caveat for its kind, and no digit", async () => {
      await renderRun(runOf(fx));
      const panel = await screen.findByTestId("instant-evidence");
      const rows = panel.querySelectorAll("li[data-gate]");
      const checks = fx.report.data_checks!;
      expect(rows.length).toBe(checks.length);
      checks.forEach((c, i) => {
        const row = rows[i]!;
        expect(row.getAttribute("data-gate")).toBe(c.gate);
        expect(row.textContent).toContain(GATE_LABELS[c.gate]);
        expect(row.textContent).toContain(STATUS_WORDS[c.status]);
        // a qualified gate carries the report's own caveat sentence for its kind
        if (c.caveat_kind) {
          const caveat = fx.report.caveats!.find((k) => k.kind === c.caveat_kind)!;
          expect(row.textContent).toContain(caveat.text);
        }
      });
      // no number leaves the frame: labels, status words and caveat sentences only
      expect(panel.textContent).not.toMatch(/\d/);
    });

    it("Limitations: every caveat text, every completion.missing entry, and the method summary", async () => {
      await renderRun(runOf(fx));
      const panel = await screen.findByTestId("instant-limitations");
      for (const c of fx.report.caveats!) {
        expect(within(screen.getByTestId("instant-caveats")).getByText(c.text)).toBeTruthy();
      }
      const missing = fx.report.completion!.missing ?? [];
      if (missing.length) {
        const block = screen.getByTestId("instant-missing");
        for (const m of missing) expect(within(block).getByText(m)).toBeTruthy();
      } else {
        expect(screen.queryByTestId("instant-missing")).toBeNull();
      }
      expect(panel.textContent).toContain(fx.report.method!.summary);
      expect(screen.getByTestId("instant-completion").textContent).toBe(
        fx.report.completion!.state === "answered" ? "Answered" : "Partly answered",
      );
    });

    it("the frame is sandboxed to allow-scripts and carries the fetched export verbatim", async () => {
      const run = await renderRun(runOf(fx));
      const frame = (await screen.findByTestId("instant-report-frame")) as HTMLIFrameElement;
      expect(frame.getAttribute("sandbox")).toBe("allow-scripts");
      expect(frame.getAttribute("srcdoc")).toBe(STUB_HTML);
      expect(frame.getAttribute("referrerpolicy")).toBe("no-referrer");
      expect(calledPaths()).toContain(run.export_url);
    });

    it("downloads point at the run's export and notebook; Share waits for saved reports", async () => {
      const run = await renderRun(runOf(fx));
      const html = screen.getByTestId("instant-download-html");
      expect(html.getAttribute("href")).toBe(run.export_url);
      expect(html.hasAttribute("download")).toBe(true);
      expect(html.textContent).toBe("Interactive report (.html)");
      const nb = screen.getByTestId("instant-download-ipynb");
      expect(nb.getAttribute("href")).toBe(run.notebook_url);
      expect(nb.hasAttribute("download")).toBe(true);
      expect(nb.textContent).toBe("Notebook (.ipynb)");
      expect(screen.queryByTestId("instant-download-md")).toBeNull();
      const share = screen.getByTestId("instant-share") as HTMLButtonElement;
      expect(share.disabled).toBe(true);
      expect(share.title).toBe(SHARE_PENDING_TITLE);
    });

    it("shows nothing about agents, and never calls the report verified", async () => {
      await renderRun(runOf(fx));
      await screen.findByTestId("instant-report-frame");
      expect(document.body.textContent).not.toMatch(/agent|swarm|\bverified\b/i);
    });
  });

  it("offers the Markdown download when the run has one", async () => {
    const run = await renderRun(
      runOf(FIXTURES[0]!, { markdown_url: "/api/instant/run-x/report.md" }),
    );
    const md = screen.getByTestId("instant-download-md");
    expect(md.getAttribute("href")).toBe(run.markdown_url);
    expect(md.hasAttribute("download")).toBe(true);
  });

  it("the frame grows to the height the export posts, from its own window only", async () => {
    await renderRun(runOf(FIXTURES[0]!));
    const frame = (await screen.findByTestId("instant-report-frame")) as HTMLIFrameElement;
    expect(frame.style.height).toBe(`${REPORT_FRAME_MIN_HEIGHT}px`);
    // another window's message is ignored
    window.dispatchEvent(
      new MessageEvent("message", {
        data: { type: REPORT_HEIGHT_MESSAGE, h: 3000 },
        source: window,
      }),
    );
    expect(frame.style.height).toBe(`${REPORT_FRAME_MIN_HEIGHT}px`);
    // the frame's own message is applied
    window.dispatchEvent(
      new MessageEvent("message", {
        data: { type: REPORT_HEIGHT_MESSAGE, h: 1234.4 },
        source: frame.contentWindow,
      }),
    );
    await waitFor(() => expect(frame.style.height).toBe("1235px"));
    // and it never shrinks below the minimum
    window.dispatchEvent(
      new MessageEvent("message", {
        data: { type: REPORT_HEIGHT_MESSAGE, h: 10 },
        source: frame.contentWindow,
      }),
    );
    await waitFor(() => expect(frame.style.height).toBe(`${REPORT_FRAME_MIN_HEIGHT}px`));
  });

  it("a locked run shows the paywall card from the config copy, with no price and a disabled button", async () => {
    await renderRun(runOf(FIXTURES[1]!, { locked: true }));
    const card = screen.getByTestId("instant-paywall");
    expect(within(card).getByRole("heading").textContent).toBe(PAYWALL_COPY.title);
    expect(card.textContent).toContain(PAYWALL_COPY.body);
    const button = within(card).getByRole("button") as HTMLButtonElement;
    expect(button.textContent).toBe(PAYWALL_COPY.cta);
    expect(button.disabled).toBe(true);
    expect(card.textContent).not.toMatch(/[$€£]|\d/);
  });

  it("an unlocked run shows no paywall", async () => {
    await renderRun(runOf(FIXTURES[1]!, { locked: false }));
    await screen.findByTestId("instant-report-frame");
    expect(screen.queryByTestId("instant-paywall")).toBeNull();
    expect(document.body.textContent).not.toContain(PAYWALL_COPY.title);
  });

  it("an ask run renders the question back as chips that ask again with the chosen option", async () => {
    const askSpy = vi.spyOn(api, "askInstant").mockResolvedValue({
      status: "ready",
      dataset_id: "ds-fixture",
      question: "Which groups matter?",
      run_id: "run-after-clarify",
      recipe: "segment",
    });
    const onReady = vi.fn();
    await renderRun(
      {
        run_id: "run-ask",
        dataset_id: "ds-fixture",
        recipe: { id: "segment", version: "1.0" },
        verdict: "ask",
        question: "Which groups matter?",
        ask: {
          parameter: "dimension",
          text: "Which column holds the groups to compare?",
          options: ["region", "channel", "product_line"],
        },
      },
      onReady,
    );
    expect(screen.getByTestId("instant-verdict").textContent).toBe("One question back");
    const back = screen.getByTestId("instant-ask-back");
    expect(back.textContent).toContain("Which column holds the groups to compare?");
    const chips = within(back).getAllByRole("button");
    expect(chips.map((c) => c.textContent)).toEqual(["region", "channel", "product_line"]);
    expect(screen.queryByTestId("instant-report-frame")).toBeNull();
    expect(screen.queryByTestId("instant-evidence")).toBeNull();
    fireEvent.click(chips[1]!);
    await waitFor(() => expect(onReady).toHaveBeenCalledWith("run-after-clarify"));
    expect(askSpy).toHaveBeenCalledWith({
      dataset_id: "ds-fixture",
      question: "Which groups matter?",
      clarify: { parameter: "dimension", option: "channel" },
    });
  });

  it("a refused run shows the refusal plain and points at Deep Investigation", async () => {
    await renderRun({
      run_id: "run-refuse",
      dataset_id: "ds-fixture",
      recipe: { id: "regress", version: "1.0" },
      verdict: "refuse",
      reason: "causal_question",
      question: "Does spend cause revenue?",
      refusal: {
        reason: "causal_question",
        text: "This data cannot say what causes what; it can say what moves together.",
      },
    });
    expect(screen.getByTestId("instant-verdict").textContent).toBe("Not answered");
    const box = screen.getByTestId("instant-refusal");
    expect(box.textContent).toContain(
      "This data cannot say what causes what; it can say what moves together.",
    );
    const link = screen.getByTestId("instant-deep-link");
    expect(link.getAttribute("href")).toBe("/analysis");
    expect(link.textContent).toBe("Try Deep Investigation");
    expect(box.textContent).toMatch(/writes and runs code/);
    expect(screen.queryByTestId("instant-report-frame")).toBeNull();
    expect(screen.queryByTestId("instant-downloads")).toBeNull();
    expect(document.body.textContent).not.toMatch(/agent|swarm/i);
  });

  it("says so when the run cannot be read", async () => {
    fetchSpy.mockImplementation(async () => json({ detail: "no such run" }, 404));
    render(<ReportPage runId="run-missing" api={api} />);
    await waitFor(() => expect(screen.getByRole("alert").textContent).toMatch(/Run fetch failed/));
    expect(screen.queryByTestId("instant-report-header")).toBeNull();
  });
});
